Method.Source:
/// <summary>
/// Find InventItemPriceSim record
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_versionId">VersionId</param>
/// <param name = "_fromDate">From date</param>
/// <param name = "_priceType">Price type</param>
/// <param name = "_inventDimId">InventDimId</param>
/// <param name = "_newSiteId">SiteId</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>InventItemPriceSim record</returns>
public static InventItemPriceSim KCS_findDate(ItemId _itemId, CostingVersionId _versionId, FromDate _fromDate, 
    CostingVersionPriceType _priceType, InventDimId _inventDimId, InventSiteId _newSiteId = '', boolean _forUpdate  = false)
{
    InventItemPriceSim  inventItemPriceSim;
    InventTable         inventTable;
    InventDim           inventDim;
    InventDim           inventDimCriteria;
    InventDimParm       inventDimParm;

    if (_itemId && _versionId)
    {
        inventItemPriceSim.selectForUpdate(_forUpdate);

        inventTable = InventTable::find(_itemId);

        InventDimParm.setAllInventDim();
        inventDimCriteria = InventItemPrice::initializeInventDimCriteria(inventTable, _inventDimId);

        inventDimCriteria.InventSiteId      = InventItemPrice::changeSiteId(inventDimCriteria.InventSiteId, _newSiteId);

        select firstonly inventItemPriceSim order by FromDate desc
            where inventItemPriceSim.ItemId        == _itemId
               && inventItemPriceSim.VersionId     == _versionId
               && inventItemPriceSim.FromDate      <= _fromDate
               && inventItemPriceSim.PriceType     == _priceType
            #InventDimExistsJoin(inventItemPriceSim.inventDimId, inventDim, inventDimCriteria, inventDimParm);
    }
    return inventItemPriceSim;
}
